<?php
declare(strict_types=1); namespace Theobroma\OneC\Http;
use Theobroma\OneC\CommerceMl\OrderWriter;use Theobroma\OneC\Orders\{WooOrderMapper,WooOrderRepository};use Theobroma\OneC\Settings\Settings;
final class WordPressExchangeEndpoint {private const BATCH='theobroma_1c_batch_';public static function register():void{add_action('init',[self::class,'rewrite']);add_filter('query_vars',[self::class,'queryVars']);add_action('template_redirect',[self::class,'dispatch']);}public static function rewrite():void{add_rewrite_rule('^theobroma-1c/exchange/?$','index.php?theobroma_1c_exchange=1','top');}public static function queryVars(array$v):array{$v[]='theobroma_1c_exchange';return$v;}public static function dispatch():void{if(!(int)get_query_var('theobroma_1c_exchange'))return;if((string)($_GET['type']??'')!=='sale'){self::send(new ExchangeResponse(400,"failure\nUnsupported type"));}if(!is_ssl()&&wp_get_environment_type()==='production'){self::send(new ExchangeResponse(403,"failure\nHTTPS required"));}$s=(new Settings())->get();$repository=new WooOrderRepository();$mapper=new WooOrderMapper();$token=self::token();$controller=new ExchangeController($s['enabled'],new BasicAuthenticator($s['username'],$s['password_hash'],'wp_check_password'),function()use($repository,$mapper,$s,$token){$pending=$repository->pending($s['batch_size']);set_transient(self::BATCH.$token,array_map(fn($r)=>['order_id'=>(int)$r['order']->get_id(),'revision'=>$r['revision']],$pending),HOUR_IN_SECONDS);return(new OrderWriter())->write(array_map(fn($r)=>$mapper->map($r['order']),$pending));},function()use($repository,$token){$batch=get_transient(self::BATCH.$token);if(is_array($batch))$repository->acknowledge($batch);delete_transient(self::BATCH.$token);});self::send($controller->handle(sanitize_key((string)($_GET['mode']??'')),(string)($_SERVER['PHP_AUTH_USER']??''),(string)($_SERVER['PHP_AUTH_PW']??'')));}private static function send(ExchangeResponse$response):never{status_header($response->status);header('Content-Type: '.$response->contentType);foreach($response->headers as$n=>$v)header($n.': '.$v);echo$response->body;exit;}private static function token():string{$raw=(string)($_COOKIE['theobroma_1c_session']??($_SERVER['PHP_AUTH_USER']??'anonymous'));return hash_hmac('sha256',$raw,wp_salt('auth'));}}
